fn solve(n: i8, k: i8) -> i8 {
    // Compute the nonnegative remainder of n divided by k.
    let r = n % k;
    // The distance to the next multiple of k past n is k - r.
    let dr = k - r;
    // The minimal nonnegative distance is the smaller of r (downwards) or dr (upwards).
    std::cmp::min(r, dr)
}

